/// @brief Enumerations of error codes for push API.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 2.3.1 @endif
abstract class push_service_error_e {
  /// < Successful
  static const int PUSH_SERVICE_ERROR_NONE = 0;

  /// < Out of memory
  static const int PUSH_SERVICE_ERROR_OUT_OF_MEMORY = -12;

  /// < Invalid parameter
  static const int PUSH_SERVICE_ERROR_INVALID_PARAMETER = -22;

  /// < Not connected
  static const int PUSH_SERVICE_ERROR_NOT_CONNECTED = -29425664;

  /// < No data available
  static const int PUSH_SERVICE_ERROR_NO_DATA = -61;

  /// < Internal operation failed
  static const int PUSH_SERVICE_ERROR_OPERATION_FAILED = -1073741824;

  /// < No privilege to access the push service
  static const int PUSH_SERVICE_ERROR_PERMISSION_DENIED = -13;

  /// < Push service not supported
  static const int PUSH_SERVICE_ERROR_NOT_SUPPORTED = -1073741822;
}

/// @brief Enumeration of registration states.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 2.3.1 @endif
abstract class push_service_state_e {
  /// < Registered
  static const int PUSH_SERVICE_STATE_REGISTERED = 0;

  /// < Unregistered
  static const int PUSH_SERVICE_STATE_UNREGISTERED = 1;

  /// < To change the provisioning server IP
  static const int PUSH_SERVICE_STATE_PROVISIONING_IPCHANGE = 2;

  /// < Ping interval is changing
  static const int PUSH_SERVICE_STATE_PING_CHANGE = 3;

  /// < Error
  static const int PUSH_SERVICE_STATE_ERROR = 4;
}

/// @brief Enumeration of result.
/// @since_tizen @if MOBILE 2.3 @elseif WEARABLE 2.3.1 @endif
abstract class push_service_result_e {
  /// < Successful
  static const int PUSH_SERVICE_RESULT_SUCCESS = 0;

  /// < Request timed out
  static const int PUSH_SERVICE_RESULT_TIMEOUT = 1;

  /// < Push server error
  static const int PUSH_SERVICE_RESULT_SERVER_ERROR = 2;

  /// < System error
  static const int PUSH_SERVICE_RESULT_SYSTEM_ERROR = 3;
}

